sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.reviewRequest =
        function(request) {

            if (
                !request ||
                !request.sys_id
            ) {
                return;
            }

            window.location.href =
                "?id=hr_leave_request_review&sys_id=" +
                request.sys_id;

        };

};

sp_widget.css:
/* =========================================================
   SHELL
========================================================= */

.hla-shell {
  display: flex;
  width: 100%;
  min-height: calc(100vh - 60px);
  background: #f4f7fb;
  color: #14213d;
}

.hla-shell *,
.hla-shell *::before,
.hla-shell *::after {
  box-sizing: border-box;
}


/* =========================================================
   SIDEBAR
========================================================= */

.hla-sidebar {
  position: sticky;
  top: 0;
  width: 235px;
  min-width: 235px;
  height: calc(100vh - 60px);
  padding: 22px 14px;
  background: #063b4c;
  color: #ffffff;
  overflow-y: auto;
  align-self: flex-start;
}


/* BRAND */

.hla-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 4px 18px;
  border-bottom: 1px solid rgba(255,255,255,.12);
}

.hla-brand-icon {
  width: 42px;
  height: 42px;
  min-width: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #ffffff;
  color: #1452c8;
  border-radius: 10px;
  font-size: 18px;
  font-weight: 800;
}

.hla-brand strong {
  display: block;
  color: #ffffff;
  font-size: 16px;
}

.hla-brand span {
  display: block;
  margin-top: 2px;
  color: #b6cbd3;
  font-size: 10px;
}


/* USER */

.hla-sidebar-user {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 18px 4px;
}

.hla-sidebar-avatar {
  width: 40px;
  height: 40px;
  min-width: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #1a7184;
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
}

.hla-sidebar-user strong {
  display: block;
  color: #ffffff;
  font-size: 11px;
}

.hla-sidebar-user span {
  display: block;
  margin-top: 3px;
  color: #a7c0c8;
  font-size: 9px;
}


/* NAVIGATION */

.hla-nav-heading {
  margin: 20px 8px 8px;
  color: #85a5af;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .8px;
}

.hla-nav-item {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 42px;
  gap: 10px;
  margin-bottom: 4px;
  padding: 9px 10px;
  border-radius: 7px;
  color: #e7f2f5;
  text-decoration: none !important;
  font-size: 10px;
  font-weight: 600;
  transition: all .2s ease;
}

.hla-nav-item:hover {
  background: rgba(255,255,255,.08);
  color: #ffffff;
}

.hla-nav-item.active {
  background: #145468;
  color: #ffffff;
}

.hla-nav-item.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 8px;
  bottom: 8px;
  width: 3px;
  border-radius: 5px;
  background: #7be34d;
}

.hla-nav-icon {
  width: 17px;
  min-width: 17px;
  text-align: center;
  color: #d9ebef;
  font-size: 13px;
}

.hla-nav-item.active .hla-nav-icon {
  color: #86ef66;
}

.hla-nav-count {
  margin-left: auto;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 20px;
  background: #59d66e;
  color: #063b4c;
  font-size: 8px;
  font-weight: 800;
}


/* FOOTER */

.hla-sidebar-footer {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 30px 7px 0;
  padding-top: 14px;
  border-top: 1px solid rgba(255,255,255,.1);
  color: #9bb5bd;
  font-size: 8px;
}

.hla-security-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #5ee16f;
}


/* =========================================================
   MAIN
========================================================= */

.hla-main {
  flex: 1;
  min-width: 0;
  background: #f4f7fb;
}

.hla-page {
  max-width: 1500px;
  margin: 0 auto;
  padding: 28px 28px 45px;
}


/* =========================================================
   HEADER
========================================================= */

.hla-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-bottom: 24px;
}

.hla-header h1 {
  margin: 0 0 7px;
  font-size: 28px;
  font-weight: 700;
  color: #10245f;
}

.hla-header p {
  margin: 0;
  color: #738096;
  font-size: 12px;
  line-height: 1.6;
}

.hla-user-card {
  min-width: 210px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 14px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  box-shadow: 0 3px 12px rgba(15,23,42,.05);
}

.hla-avatar {
  width: 43px;
  height: 43px;
  min-width: 43px;
  border-radius: 50%;
  background: #e8f0ff;
  color: #2856c7;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
}

.hla-user-card strong {
  display: block;
  color: #172554;
  font-size: 11px;
}

.hla-user-card span {
  display: block;
  margin-top: 3px;
  color: #8490a5;
  font-size: 9px;
}


/* =========================================================
   KPI CARDS
========================================================= */

.hla-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 16px;
  margin-bottom: 22px;
}

.hla-kpi-card {
  min-height: 145px;
  display: flex;
  align-items: flex-start;
  gap: 15px;
  padding: 20px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  box-shadow: 0 4px 15px rgba(15,23,42,.05);
  text-decoration: none !important;
  transition: transform .2s ease,
              box-shadow .2s ease;
}

.hla-kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 22px rgba(15,23,42,.08);
}

.hla-kpi-icon {
  width: 48px;
  height: 48px;
  min-width: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 21px;
  font-weight: 700;
}

.hla-kpi-card.pending .hla-kpi-icon {
  background: #fff4d8;
  color: #c97b00;
}

.hla-kpi-card.approved .hla-kpi-icon {
  background: #dcfce7;
  color: #15803d;
}

.hla-kpi-card.rejected .hla-kpi-icon {
  background: #fee2e2;
  color: #b91c1c;
}

.hla-kpi-card.total .hla-kpi-icon {
  background: #e8efff;
  color: #315ecf;
}

.hla-kpi-content {
  flex: 1;
}

.hla-kpi-label {
  display: block;
  margin-bottom: 7px;
  color: #49566f;
  font-size: 11px;
  font-weight: 700;
}

.hla-kpi-number {
  display: block;
  margin-bottom: 5px;
  color: #10245f;
  font-size: 29px;
  line-height: 1;
}

.hla-kpi-content p {
  margin: 0;
  color: #8792a6;
  font-size: 9px;
  line-height: 1.5;
}


/* =========================================================
   CARD
========================================================= */

.hla-card {
  scroll-margin-top: 20px;
  margin-bottom: 22px;
  padding: 21px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  box-shadow: 0 4px 15px rgba(15,23,42,.045);
}

.hla-section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 15px;
  margin-bottom: 18px;
}

.hla-section-header h2 {
  margin: 0 0 5px;
  color: #152354;
  font-size: 17px;
  font-weight: 700;
}

.hla-section-header p {
  margin: 0;
  max-width: 720px;
  color: #7b879c;
  font-size: 10px;
  line-height: 1.55;
}

.hla-count-badge {
  padding: 7px 12px;
  border-radius: 20px;
  background: #fff4d8;
  color: #b56600;
  font-size: 9px;
  font-weight: 700;
  white-space: nowrap;
}

.analytics-badge {
  padding: 7px 11px;
  border-radius: 18px;
  background: #e8efff;
  color: #315ecf;
  font-size: 8px;
  font-weight: 700;
}


/* =========================================================
   TABLE
========================================================= */

.hla-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.hla-table {
  width: 100%;
  min-width: 1120px;
  border-collapse: collapse;
}

.hla-table thead {
  background: #f6f8fc;
}

.hla-table th {
  padding: 11px 10px;
  border-bottom: 1px solid #e5eaf1;
  text-align: left;
  color: #47536b;
  font-size: 9px;
  font-weight: 700;
  white-space: nowrap;
}

.hla-table td {
  padding: 12px 10px;
  border-bottom: 1px solid #edf0f4;
  vertical-align: middle;
  color: #334155;
  font-size: 9px;
}

.hla-table tbody tr:hover {
  background: #fafcff;
}

.hla-table tbody tr:last-child td {
  border-bottom: none;
}

.request-number {
  display: block;
  margin-bottom: 4px;
  color: #1769e0;
  font-size: 9px;
}

.hla-table td small {
  color: #94a3b8;
  font-size: 7px;
}

.department-pill {
  display: inline-block;
  padding: 5px 8px;
  border-radius: 14px;
  background: #eef2ff;
  color: #4054b2;
  font-size: 8px;
  font-weight: 600;
}

.date-range {
  display: flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}

.date-arrow {
  color: #94a3b8;
}

.muted {
  color: #94a3b8;
  font-style: italic;
}

.status-pill {
  display: inline-block;
  padding: 5px 9px;
  border-radius: 14px;
  font-size: 8px;
  font-weight: 700;
  white-space: nowrap;
}

.pending-status {
  background: #fff4d8;
  color: #b56600;
}

.hla-review-btn {
  min-width: 68px;
  padding: 7px 11px;
  border: 1px solid #2e9148;
  border-radius: 7px;
  background: #ffffff;
  color: #23783a;
  cursor: pointer;
  font-size: 8px;
  font-weight: 700;
  transition: .2s;
}

.hla-review-btn:hover {
  background: #ecfdf3;
}


/* =========================================================
   EMPTY
========================================================= */

.hla-empty {
  padding: 42px 20px;
  text-align: center;
}

.hla-empty.small {
  padding: 24px 10px;
  color: #94a3b8;
  font-size: 9px;
}

.hla-empty-icon {
  width: 55px;
  height: 55px;
  margin: 0 auto 14px;
  border-radius: 50%;
  background: #dcfce7;
  color: #15803d;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 27px;
  font-weight: 700;
}

.hla-empty h3 {
  margin: 0 0 5px;
  color: #172554;
  font-size: 16px;
}

.hla-empty p {
  margin: 0;
  color: #94a3b8;
  font-size: 10px;
}


/* =========================================================
   ANALYTICS
========================================================= */

.hla-analytics-grid {
  scroll-margin-top: 20px;
  display: grid;
  grid-template-columns: 1.35fr .85fr;
  gap: 20px;
}


/* DEPARTMENT */

.department-list {
  max-height: 530px;
  overflow-y: auto;
  padding-right: 5px;
}

.department-row {
  padding: 14px 0;
  border-bottom: 1px solid #edf0f4;
}

.department-row:last-child {
  border-bottom: none;
}

.department-row-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.department-row-header strong {
  color: #172554;
  font-size: 10px;
}

.department-row-header span {
  margin-left: 8px;
  color: #94a3b8;
  font-size: 8px;
}

.department-total {
  min-width: 25px;
  text-align: right;
  color: #315ecf !important;
  font-size: 11px !important;
}

.analytics-bar {
  width: 100%;
  height: 7px;
  overflow: hidden;
  margin-bottom: 9px;
  border-radius: 10px;
  background: #eef2f7;
}

.analytics-bar-fill {
  height: 100%;
  min-width: 4px;
  border-radius: 10px;
  background: linear-gradient(
    90deg,
    #4f6ee8,
    #7387ec
  );
}

.department-stats {
  display: grid;
  grid-template-columns:
    repeat(4,minmax(0,1fr));
  gap: 8px;
}

.department-stats span {
  color: #8691a5;
  font-size: 7px;
}

.department-stats strong {
  margin-left: 3px;
  color: #334155;
  font-size: 8px;
}


/* LEAVE TYPE */

.leave-type-row {
  margin-bottom: 18px;
}

.leave-type-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 7px;
}

.leave-type-header span {
  color: #445066;
  font-size: 9px;
}

.leave-type-header strong {
  color: #172554;
  font-size: 9px;
}

.leave-type-bar {
  width: 100%;
  height: 7px;
  overflow: hidden;
  border-radius: 10px;
  background: #eef2f7;
}

.leave-type-fill {
  height: 100%;
  min-width: 4px;
  border-radius: 10px;
  background: linear-gradient(
    90deg,
    #20a77b,
    #42c596
  );
}


/* =========================================================
   STATUS
========================================================= */

.status-overview {
  display: flex;
  align-items: center;
  gap: 45px;
  padding: 10px 5px 5px;
}

.status-donut {
  position: relative;
  width: 180px;
  height: 180px;
  min-width: 180px;
  border-radius: 50%;
}

.status-donut::after {
  content: "";
  position: absolute;
  inset: 38px;
  border-radius: 50%;
  background: #ffffff;
}

.status-donut-center {
  position: absolute;
  z-index: 2;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.status-donut-center strong {
  color: #172554;
  font-size: 25px;
}

.status-donut-center span {
  margin-top: 2px;
  color: #94a3b8;
  font-size: 9px;
}

.status-legend {
  flex: 1;
  max-width: 500px;
}

.legend-item {
  display: grid;
  grid-template-columns:
    12px 1fr auto;
  align-items: center;
  gap: 9px;
  padding: 10px 0;
  border-bottom: 1px solid #edf0f4;
}

.legend-item:last-child {
  border-bottom: none;
}

.legend-item > span:nth-child(2) {
  color: #4a5568;
  font-size: 9px;
}

.legend-item strong {
  color: #172554;
  font-size: 10px;
}

.legend-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
}

.pending-dot {
  background: #f59e0b;
}

.approved-dot {
  background: #22c55e;
}

.rejected-dot {
  background: #ef4444;
}

.cancelled-dot {
  background: #8b5cf6;
}


/* =========================================================
   ACCESS DENIED
========================================================= */

.hla-access-denied {
  max-width: 600px;
  margin: 80px auto;
  padding: 35px;
  text-align: center;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  box-shadow: 0 6px 20px rgba(15,23,42,.07);
}

.access-icon {
  margin-bottom: 12px;
  font-size: 35px;
}

.hla-access-denied h2 {
  margin: 0 0 8px;
  color: #172554;
}

.hla-access-denied p {
  margin: 0 0 18px;
  color: #738096;
  font-size: 11px;
}

.hla-access-denied a {
  color: #1769e0;
  text-decoration: none;
  font-size: 10px;
  font-weight: 600;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .hla-sidebar {
    width: 210px;
    min-width: 210px;
  }

  .hla-kpi-grid {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }

  .hla-analytics-grid {
    grid-template-columns: 1fr;
  }

}


@media (max-width: 760px) {

  .hla-shell {
    display: block;
  }

  .hla-sidebar {
    position: relative;
    width: 100%;
    min-width: 100%;
    height: auto;
  }

  .hla-page {
    padding: 20px 14px 35px;
  }

  .hla-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .hla-user-card {
    width: 100%;
  }

  .hla-kpi-grid {
    grid-template-columns: 1fr;
  }

  .status-overview {
    flex-direction: column;
    align-items: flex-start;
    gap: 24px;
  }

  .department-stats {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }

}

sp_widget.script:
(function() {

    // =====================================================
    // CONSTANTS
    // =====================================================

    var LEAVE_TABLE =
        'x_snc_unified_hr_0_leave_request';

    var HR_APPROVAL_GROUP =
        'HR Team';


    // =====================================================
    // LOGGED-IN USER
    // =====================================================

    data.userId =
        gs.getUserID();

    data.userName =
        gs.getUserDisplayName();

    data.initials = "";

    data.hasAccess = false;

    data.error = false;

    data.message = "";


    var nameParts =
        (data.userName || "").split(" ");

    for (
        var i = 0;
        i < nameParts.length && i < 2;
        i++
    ) {

        if (nameParts[i]) {

            data.initials +=
                nameParts[i]
                    .charAt(0)
                    .toUpperCase();
        }
    }


    // =====================================================
    // ACCESS CHECK
    // =====================================================

    var currentUser =
        gs.getUser();


    if (
        !currentUser.isMemberOf(
            HR_APPROVAL_GROUP
        )
    ) {

        data.error = true;

        data.message =
            "You are not authorized to access the HR Leave Approval Dashboard.";

        return;
    }


    data.hasAccess = true;



    // =====================================================
    // INITIALIZE DASHBOARD DATA
    // =====================================================

    data.pendingCount = 0;

    data.approvedThisMonth = 0;

    data.rejectedThisMonth = 0;

    data.totalThisMonth = 0;


    data.pendingRequests = [];

    data.departmentAnalytics = [];

    data.leaveTypeAnalytics = [];


    data.statusAnalytics = {

        pendingHR: 0,

        approved: 0,

        rejected: 0,

        cancelled: 0,

        total: 0

    };


    // =====================================================
    // PENDING HR APPROVAL COUNT
    // =====================================================

    var pendingGA =
        new GlideAggregate(
            LEAVE_TABLE
        );

    pendingGA.addQuery(
        'status',
        'pending_hr'
    );

    pendingGA.addAggregate(
        'COUNT'
    );

    pendingGA.query();


    if (
        pendingGA.next()
    ) {

        data.pendingCount =
            parseInt(
                pendingGA.getAggregate(
                    'COUNT'
                ),
                10
            ) || 0;
    }



    // =====================================================
    // APPROVED THIS MONTH
    // =====================================================

    var approvedGA =
        new GlideAggregate(
            LEAVE_TABLE
        );

    approvedGA.addQuery(
        'status',
        'approved'
    );

    approvedGA.addQuery(
        'sys_updated_on',
        '>=',
        gs.beginningOfThisMonth()
    );

    approvedGA.addQuery(
        'sys_updated_on',
        '<=',
        gs.endOfThisMonth()
    );

    approvedGA.addAggregate(
        'COUNT'
    );

    approvedGA.query();


    if (
        approvedGA.next()
    ) {

        data.approvedThisMonth =
            parseInt(
                approvedGA.getAggregate(
                    'COUNT'
                ),
                10
            ) || 0;
    }



    // =====================================================
    // REJECTED THIS MONTH
    // =====================================================

    var rejectedGA =
        new GlideAggregate(
            LEAVE_TABLE
        );

    rejectedGA.addQuery(
        'status',
        'rejected'
    );

    rejectedGA.addQuery(
        'sys_updated_on',
        '>=',
        gs.beginningOfThisMonth()
    );

    rejectedGA.addQuery(
        'sys_updated_on',
        '<=',
        gs.endOfThisMonth()
    );

    rejectedGA.addAggregate(
        'COUNT'
    );

    rejectedGA.query();


    if (
        rejectedGA.next()
    ) {

        data.rejectedThisMonth =
            parseInt(
                rejectedGA.getAggregate(
                    'COUNT'
                ),
                10
            ) || 0;
    }



    // =====================================================
    // TOTAL REQUESTS THIS MONTH
    // =====================================================

    var monthGA =
        new GlideAggregate(
            LEAVE_TABLE
        );

    monthGA.addQuery(
        'applied_on',
        '>=',
        gs.beginningOfThisMonth()
    );

    monthGA.addQuery(
        'applied_on',
        '<=',
        gs.endOfThisMonth()
    );

    monthGA.addAggregate(
        'COUNT'
    );

    monthGA.query();


    if (
        monthGA.next()
    ) {

        data.totalThisMonth =
            parseInt(
                monthGA.getAggregate(
                    'COUNT'
                ),
                10
            ) || 0;
    }



    // =====================================================
    // PENDING HR LEAVE REQUESTS
    // =====================================================

    var leaveGR =
        new GlideRecord(
            LEAVE_TABLE
        );

    leaveGR.addQuery(
        'status',
        'pending_hr'
    );

    leaveGR.orderByDesc(
        'applied_on'
    );

    leaveGR.setLimit(20);

    leaveGR.query();


    while (
        leaveGR.next()
    ) {

        data.pendingRequests.push({

            sys_id:
                leaveGR.getUniqueValue(),

            number:
                leaveGR.getDisplayValue(
                    'number'
                ),

            employee:
                leaveGR.getDisplayValue(
                    'requested_by'
                ),

            department:
                leaveGR.getDisplayValue(
                    'department'
                ),

            leave_type:
                leaveGR.getDisplayValue(
                    'leave_type'
                ),

            start_date:
                leaveGR.getDisplayValue(
                    'start_date'
                ),

            end_date:
                leaveGR.getDisplayValue(
                    'end_date'
                ),

            number_of_days:
                leaveGR.getDisplayValue(
                    'number_of_leave_days'
                ),

            reason:
                leaveGR.getDisplayValue(
                    'reason'
                ),

            hod_remarks:
                leaveGR.getDisplayValue(
                    'hod_remarks'
                ),

            hr_remarks:
                leaveGR.getDisplayValue(
                    'hr_remarks'
                ),

            approval_group:
                leaveGR.getDisplayValue(
                    'approval_group'
                ),

            current_approver:
                leaveGR.getDisplayValue(
                    'current_approver'
                ),

            applied_on:
                leaveGR.getDisplayValue(
                    'applied_on'
                ),

            status:
                leaveGR.getDisplayValue(
                    'status'
                ),

            status_value:
                leaveGR.getValue(
                    'status'
                )

        });
    }



    // =====================================================
    // DEPARTMENT-WISE LEAVE ANALYTICS
    // =====================================================

    var departmentMap = {};

    var departmentGR =
        new GlideRecord(
            LEAVE_TABLE
        );

    departmentGR.query();


    while (
        departmentGR.next()
    ) {

        var departmentName =
            departmentGR.getDisplayValue(
                'department'
            );


        if (!departmentName) {

            departmentName =
                'Not Specified';
        }


        if (
            !departmentMap[
                departmentName
            ]
        ) {

            departmentMap[
                departmentName
            ] = {

                name:
                    departmentName,

                total:
                    0,

                pending:
                    0,

                approved:
                    0,

                rejected:
                    0,

                leave_days:
                    0

            };
        }


        departmentMap[
            departmentName
        ].total++;


        var status =
            departmentGR.getValue(
                'status'
            );


        if (
            status ==
            'pending_hr'
        ) {

            departmentMap[
                departmentName
            ].pending++;
        }


        if (
            status ==
            'approved'
        ) {

            departmentMap[
                departmentName
            ].approved++;
        }


        if (
            status ==
            'rejected'
        ) {

            departmentMap[
                departmentName
            ].rejected++;
        }


        var leaveDays =
            parseInt(
                departmentGR.getValue(
                    'number_of_leave_days'
                ),
                10
            ) || 0;


        departmentMap[
            departmentName
        ].leave_days +=
            leaveDays;
    }


    var maxDepartmentCount = 0;


    for (
        var deptName
        in departmentMap
    ) {

        if (
            departmentMap[
                deptName
            ].total >
            maxDepartmentCount
        ) {

            maxDepartmentCount =
                departmentMap[
                    deptName
                ].total;
        }
    }


    for (
        var departmentName
        in departmentMap
    ) {

        var departmentItem =
            departmentMap[
                departmentName
            ];


        departmentItem.percentage =
            maxDepartmentCount > 0
            ?
            Math.round(
                (
                    departmentItem.total /
                    maxDepartmentCount
                ) * 100
            )
            :
            0;


        data.departmentAnalytics.push(
            departmentItem
        );
    }


    data.departmentAnalytics.sort(
        function(a, b) {

            return (
                b.total -
                a.total
            );
        }
    );



    // =====================================================
    // LEAVE TYPE ANALYTICS
    // =====================================================

    var leaveTypeMap = {};

    var typeGR =
        new GlideRecord(
            LEAVE_TABLE
        );

    typeGR.query();


    while (
        typeGR.next()
    ) {

        var leaveType =
            typeGR.getDisplayValue(
                'leave_type'
            );


        if (!leaveType) {

            leaveType =
                'Not Specified';
        }


        if (
            !leaveTypeMap[
                leaveType
            ]
        ) {

            leaveTypeMap[
                leaveType
            ] = 0;
        }


        leaveTypeMap[
            leaveType
        ]++;
    }


    var maxTypeCount = 0;


    for (
        var typeName
        in leaveTypeMap
    ) {

        if (
            leaveTypeMap[
                typeName
            ] >
            maxTypeCount
        ) {

            maxTypeCount =
                leaveTypeMap[
                    typeName
                ];
        }
    }


    for (
        var leaveTypeName
        in leaveTypeMap
    ) {

        var leaveTypeCount =
            leaveTypeMap[
                leaveTypeName
            ];


        data.leaveTypeAnalytics.push({

            name:
                leaveTypeName,

            count:
                leaveTypeCount,

            percentage:
                maxTypeCount > 0
                ?
                Math.round(
                    (
                        leaveTypeCount /
                        maxTypeCount
                    ) * 100
                )
                :
                0

        });
    }


    data.leaveTypeAnalytics.sort(
        function(a, b) {

            return (
                b.count -
                a.count
            );
        }
    );



    // =====================================================
    // STATUS ANALYTICS
    // =====================================================

    var statusGR =
        new GlideRecord(
            LEAVE_TABLE
        );

    statusGR.query();


    while (
        statusGR.next()
    ) {

        var statusValue =
            statusGR.getValue(
                'status'
            );


        data.statusAnalytics.total++;


        if (
            statusValue ==
            'pending_hr'
        ) {

            data.statusAnalytics
                .pendingHR++;
        }


        if (
            statusValue ==
            'approved'
        ) {

            data.statusAnalytics
                .approved++;
        }


        if (
            statusValue ==
            'rejected'
        ) {

            data.statusAnalytics
                .rejected++;
        }


        if (
            statusValue ==
            'cancelled'
        ) {

            data.statusAnalytics
                .cancelled++;
        }
    }



    // =====================================================
    // STATUS DONUT GRADIENT
    // =====================================================

    function buildGradient(
        values,
        colors
    ) {

        var total = 0;

        var j;


        for (
            j = 0;
            j < values.length;
            j++
        ) {

            total +=
                values[j];
        }


        if (
            total == 0
        ) {

            return '#e5e7eb';
        }


        var current = 0;

        var pieces = [];


        for (
            j = 0;
            j < values.length;
            j++
        ) {

            if (
                values[j] == 0
            ) {

                continue;
            }


            var start =
                (
                    current /
                    total
                ) * 100;


            current +=
                values[j];


            var end =
                (
                    current /
                    total
                ) * 100;


            pieces.push(
                colors[j] +
                ' ' +
                start +
                '% ' +
                end +
                '%'
            );
        }


        return (
            'conic-gradient(' +
            pieces.join(',') +
            ')'
        );
    }


    data.statusDonutGradient =
        buildGradient(
            [
                data.statusAnalytics.pendingHR,
                data.statusAnalytics.approved,
                data.statusAnalytics.rejected,
                data.statusAnalytics.cancelled
            ],
            [
                '#f59e0b',
                '#22c55e',
                '#ef4444',
                '#8b5cf6'
            ]
        );

})();
